-- ############################################################
-- # 001_create_users.sql
-- ############################################################

-- ============================================================
-- Migration 001 : users
-- Core account table. Roles are NEVER chosen by the client:
-- the API always inserts 'student'; admins are promoted manually.
-- Only @gmail.com addresses are accepted (relaxed in migration 009).
--
-- PORTED FROM MySQL: this project originally ran on MySQL. The
-- differences that matter across every migration file:
--   AUTO_INCREMENT      -> GENERATED BY DEFAULT AS IDENTITY
--                          ("BY DEFAULT", not "ALWAYS", so seed.sql can
--                           still insert explicit ids)
--   ENUM('a','b')       -> VARCHAR + CHECK constraint. A native PostgreSQL
--                          enum would also work, but a CHECK keeps every
--                          column plain text, so the driver never has to
--                          cast a bound parameter into a custom type.
--   KEY idx_... (...)   -> a separate CREATE INDEX statement
--   COMMENT '...'       -> COMMENT ON COLUMN
--   ON UPDATE CURRENT_TIMESTAMP -> set_updated_at(), the trigger below
--   REGEXP              -> the ~ operator
-- ============================================================

-- ------------------------------------------------------------
-- Shared trigger function: MySQL keeps updated_at current by itself with
-- "ON UPDATE CURRENT_TIMESTAMP". PostgreSQL has no such column clause, so
-- every table below attaches this BEFORE UPDATE trigger instead.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at := CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS users (
  user_id       INTEGER      GENERATED BY DEFAULT AS IDENTITY,
  name          VARCHAR(100) NOT NULL,
  email         VARCHAR(191) NOT NULL,
  tnt           VARCHAR(30)  NOT NULL,
  academic_year VARCHAR(30)  NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role          VARCHAR(16)  NOT NULL DEFAULT 'student',
  created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_users PRIMARY KEY (user_id),
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT uq_users_tnt   UNIQUE (tnt),
  CONSTRAINT chk_users_role
    CHECK (role IN ('student', 'admin')),
  CONSTRAINT chk_users_email_gmail
    CHECK (email ~ '^[a-z0-9._%+-]+@gmail\.com$'),
  CONSTRAINT chk_users_name_not_blank
    CHECK (char_length(trim(name)) >= 2)
);

COMMENT ON COLUMN users.tnt           IS 'University roll / TNT number, unique per student';
COMMENT ON COLUMN users.academic_year IS 'e.g. "1st Year", "2nd Year", "Final Year"';
COMMENT ON COLUMN users.password_hash IS 'bcrypt hash - plaintext is never stored';

CREATE INDEX IF NOT EXISTS idx_users_role ON users (role);

DROP TRIGGER IF EXISTS trg_users_updated_at ON users;
CREATE TRIGGER trg_users_updated_at
BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- ############################################################
-- # 002_create_study_buddy_profiles.sql
-- ############################################################

-- ============================================================
-- Migration 002 : study_buddy_profiles
-- Exactly ONE profile per user (enforced by uq_profiles_user_id).
-- telegram / viber are PRIVATE columns: the repository layer has
-- a "public" projection that never selects them, and they are only
-- read through the match-aware query path.
-- ============================================================

CREATE TABLE IF NOT EXISTS study_buddy_profiles (
  profile_id      INTEGER       GENERATED BY DEFAULT AS IDENTITY,
  user_id         INTEGER       NOT NULL,
  nickname        VARCHAR(60)   NOT NULL,
  semester        VARCHAR(30)   NOT NULL,
  study_style     VARCHAR(20)   NOT NULL DEFAULT 'mixed',
  weak_subjects   VARCHAR(500)  NULL,
  strong_subjects VARCHAR(500)  NULL,
  wanna_meet      VARCHAR(12)   NOT NULL DEFAULT 'both',
  notes           VARCHAR(1000) NULL,
  telegram        VARCHAR(100)  NULL,
  viber           VARCHAR(100)  NULL,
  created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_profiles PRIMARY KEY (profile_id),
  CONSTRAINT uq_profiles_user_id UNIQUE (user_id),
  CONSTRAINT fk_profiles_user
    FOREIGN KEY (user_id) REFERENCES users (user_id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT chk_profiles_study_style
    CHECK (study_style IN ('solo_focus', 'group_discussion', 'quiet_library', 'online_call', 'mixed')),
  CONSTRAINT chk_profiles_wanna_meet
    CHECK (wanna_meet IN ('online', 'in_person', 'both')),
  CONSTRAINT chk_profiles_has_contact
    CHECK (telegram IS NOT NULL OR viber IS NOT NULL)
);

COMMENT ON COLUMN study_buddy_profiles.semester        IS 'e.g. "Semester 1" ... "Semester 8"';
COMMENT ON COLUMN study_buddy_profiles.weak_subjects   IS 'Comma separated subject list';
COMMENT ON COLUMN study_buddy_profiles.strong_subjects IS 'Comma separated subject list';
COMMENT ON COLUMN study_buddy_profiles.telegram        IS 'PRIVATE - @username or t.me link, revealed only on mutual match';
COMMENT ON COLUMN study_buddy_profiles.viber           IS 'PRIVATE - phone or viber link, revealed only on mutual match';

CREATE INDEX IF NOT EXISTS idx_profiles_semester    ON study_buddy_profiles (semester);
CREATE INDEX IF NOT EXISTS idx_profiles_study_style ON study_buddy_profiles (study_style);
CREATE INDEX IF NOT EXISTS idx_profiles_wanna_meet  ON study_buddy_profiles (wanna_meet);

DROP TRIGGER IF EXISTS trg_profiles_updated_at ON study_buddy_profiles;
CREATE TRIGGER trg_profiles_updated_at
BEFORE UPDATE ON study_buddy_profiles
FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- ############################################################
-- # 003_create_buddy_requests.sql
-- ############################################################

-- ============================================================
-- Migration 003 : buddy_requests
-- One row per (sender -> receiver) direction.
--   * trg_requests_not_self_* : a user can never request themselves
--   * uq_requests_pair        : no duplicate request in the same direction
--                               (a rejected row is revived to 'pending'
--                                by the service instead of inserting a dup)
-- A MUTUAL MATCH is simply status = 'accepted'.
--
-- WHY A TRIGGER AND NOT A CHECK CONSTRAINT
-- PostgreSQL would happily accept CHECK (sender_id <> receiver_id) here -
-- the restriction that forced a trigger was MySQL's, which prohibits foreign
-- key referential actions on any column named in a CHECK. The trigger is kept
-- so the rejection message stays identical to the one the API already
-- surfaces, and so this file still mirrors the schema it was ported from.
-- ============================================================

CREATE TABLE IF NOT EXISTS buddy_requests (
  request_id  INTEGER     GENERATED BY DEFAULT AS IDENTITY,
  sender_id   INTEGER     NOT NULL,
  receiver_id INTEGER     NOT NULL,
  status      VARCHAR(12) NOT NULL DEFAULT 'pending',
  created_at  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_requests PRIMARY KEY (request_id),
  CONSTRAINT uq_requests_pair UNIQUE (sender_id, receiver_id),
  CONSTRAINT fk_requests_sender
    FOREIGN KEY (sender_id) REFERENCES users (user_id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_requests_receiver
    FOREIGN KEY (receiver_id) REFERENCES users (user_id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT chk_requests_status
    CHECK (status IN ('pending', 'accepted', 'rejected'))
);

CREATE INDEX IF NOT EXISTS idx_requests_receiver_status ON buddy_requests (receiver_id, status);
CREATE INDEX IF NOT EXISTS idx_requests_sender_status   ON buddy_requests (sender_id, status);

-- MySQL raised this with SIGNAL SQLSTATE '45000'; the PostgreSQL equivalent
-- is RAISE EXCEPTION, which reports SQLSTATE P0001. error.middleware.js maps
-- P0001 to a 422 and shows the message text, exactly as it did for 45000.
CREATE OR REPLACE FUNCTION trg_requests_not_self()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.sender_id = NEW.receiver_id THEN
    RAISE EXCEPTION 'You cannot send a buddy request to yourself';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_requests_not_self_bi ON buddy_requests;
CREATE TRIGGER trg_requests_not_self_bi
BEFORE INSERT ON buddy_requests
FOR EACH ROW EXECUTE FUNCTION trg_requests_not_self();

DROP TRIGGER IF EXISTS trg_requests_not_self_bu ON buddy_requests;
CREATE TRIGGER trg_requests_not_self_bu
BEFORE UPDATE ON buddy_requests
FOR EACH ROW EXECUTE FUNCTION trg_requests_not_self();

DROP TRIGGER IF EXISTS trg_requests_updated_at ON buddy_requests;
CREATE TRIGGER trg_requests_updated_at
BEFORE UPDATE ON buddy_requests
FOR EACH ROW EXECUTE FUNCTION set_updated_at();


