-- ############################################################
-- # 006_create_polls.sql
-- ############################################################

-- ============================================================
-- Migration 006 : polls, poll_options, votes
--
-- "One vote per user per poll" is enforced BY THE DATABASE with
--   UNIQUE (poll_id, user_id)  -> uq_votes_one_per_poll
--
-- A vote can also never point at an option from a different poll:
-- votes carries (poll_id, option_id) and a COMPOSITE foreign key
-- into poll_options (poll_id, option_id). No trigger needed.
-- ============================================================

CREATE TABLE IF NOT EXISTS polls (
  poll_id     INTEGER      GENERATED BY DEFAULT AS IDENTITY,
  question    VARCHAR(255) NOT NULL,
  description VARCHAR(500) NULL,
  status      VARCHAR(8)   NOT NULL DEFAULT 'open',
  ends_at     TIMESTAMP    NULL,
  created_by  INTEGER      NULL,
  created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_polls PRIMARY KEY (poll_id),
  CONSTRAINT fk_polls_created_by
    FOREIGN KEY (created_by) REFERENCES users (user_id)
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT chk_polls_status
    CHECK (status IN ('open', 'closed'))
);

COMMENT ON COLUMN polls.ends_at    IS 'Optional auto-close deadline';
COMMENT ON COLUMN polls.created_by IS 'FK -> users.user_id, must be an admin (see trigger)';

CREATE INDEX IF NOT EXISTS idx_polls_status     ON polls (status);
CREATE INDEX IF NOT EXISTS idx_polls_created_by ON polls (created_by);

CREATE TABLE IF NOT EXISTS poll_options (
  option_id     INTEGER      GENERATED BY DEFAULT AS IDENTITY,
  poll_id       INTEGER      NOT NULL,
  option_text   VARCHAR(200) NOT NULL,
  display_order SMALLINT     NOT NULL DEFAULT 0,
  created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_poll_options PRIMARY KEY (option_id),
  -- Not redundant: the composite FK on votes needs this exact key to
  -- reference, which is what stops a vote pointing at another poll's option.
  CONSTRAINT uq_options_poll_option UNIQUE (poll_id, option_id),
  CONSTRAINT uq_options_poll_text   UNIQUE (poll_id, option_text),
  CONSTRAINT fk_options_poll
    FOREIGN KEY (poll_id) REFERENCES polls (poll_id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT chk_options_display_order
    CHECK (display_order >= 0)
);

CREATE TABLE IF NOT EXISTS votes (
  vote_id    INTEGER   GENERATED BY DEFAULT AS IDENTITY,
  poll_id    INTEGER   NOT NULL,
  option_id  INTEGER   NOT NULL,
  user_id    INTEGER   NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_votes PRIMARY KEY (vote_id),
  CONSTRAINT uq_votes_one_per_poll UNIQUE (poll_id, user_id),
  CONSTRAINT fk_votes_option
    FOREIGN KEY (poll_id, option_id) REFERENCES poll_options (poll_id, option_id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_votes_user
    FOREIGN KEY (user_id) REFERENCES users (user_id)
    ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_votes_option ON votes (option_id);
CREATE INDEX IF NOT EXISTS idx_votes_user   ON votes (user_id);

DROP TRIGGER IF EXISTS trg_polls_updated_at ON polls;
CREATE TRIGGER trg_polls_updated_at
BEFORE UPDATE ON polls
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_options_updated_at ON poll_options;
CREATE TRIGGER trg_options_updated_at
BEFORE UPDATE ON poll_options
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_votes_updated_at ON votes;
CREATE TRIGGER trg_votes_updated_at
BEFORE UPDATE ON votes
FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- ############################################################
-- # 007_create_notifications.sql
-- ############################################################

-- ============================================================
-- Migration 007 : notifications
-- Fan-out rows, one per recipient. A user may only ever read
-- rows where notifications.user_id = the authenticated user_id.
-- reference_type / reference_id let the frontend deep-link
-- (e.g. buddy_request 12  ->  /requests/12).
-- ============================================================

CREATE TABLE IF NOT EXISTS notifications (
  notification_id INTEGER      GENERATED BY DEFAULT AS IDENTITY,
  user_id         INTEGER      NOT NULL,
  type            VARCHAR(32)  NOT NULL,
  title           VARCHAR(150) NOT NULL,
  message         VARCHAR(500) NULL,
  reference_type  VARCHAR(16)  NULL,
  reference_id    INTEGER      NULL,
  -- MySQL used TINYINT(1) holding 0/1 and the repository binds 0/1 literals.
  -- SMALLINT keeps that contract; a BOOLEAN would break `is_read = 0`.
  is_read         SMALLINT     NOT NULL DEFAULT 0,
  created_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_notifications PRIMARY KEY (notification_id),
  CONSTRAINT fk_notifications_user
    FOREIGN KEY (user_id) REFERENCES users (user_id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT chk_notifications_type
    CHECK (type IN (
      'buddy_request',
      'buddy_request_accepted',
      'buddy_request_rejected',
      'new_competition',
      'new_lost_found',
      'new_poll'
    )),
  CONSTRAINT chk_notifications_reference_type
    CHECK (reference_type IS NULL OR reference_type IN (
      'buddy_request', 'competition', 'lost_found', 'poll'
    )),
  CONSTRAINT chk_notifications_is_read
    CHECK (is_read IN (0, 1))
);

COMMENT ON COLUMN notifications.user_id IS 'Recipient';

CREATE INDEX IF NOT EXISTS idx_notifications_user_read
  ON notifications (user_id, is_read, created_at);

DROP TRIGGER IF EXISTS trg_notifications_updated_at ON notifications;
CREATE TRIGGER trg_notifications_updated_at
BEFORE UPDATE ON notifications
FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- ############################################################
-- # 008_create_views_and_triggers.sql
-- ############################################################

-- ============================================================
-- Migration 008 : views + integrity triggers
--
-- VIEWS
--   v_buddy_matches  : an accepted request expanded into BOTH
--                      directions, so "my matches" is one indexed
--                      lookup instead of an OR across two columns.
--   v_poll_results   : per-option vote counts + percentage.
--
-- TRIGGERS (defence in depth - the API already checks the role)
--   competitions / polls : created_by must be an admin user
--   votes                : cannot vote on a closed / expired poll
--
-- MySQL -> PostgreSQL notes for this file:
--   SIGNAL SQLSTATE '45000'  -> RAISE EXCEPTION (SQLSTATE P0001)
--   NEW.x <=> OLD.x          -> NEW.x IS NOT DISTINCT FROM OLD.x
--   trigger body inline      -> a named FUNCTION the trigger calls
--   ROUND(bigint / .., 2)    -> the numerator is cast to numeric first,
--                               because PostgreSQL has no two-argument
--                               ROUND for double precision.
-- ============================================================

CREATE OR REPLACE VIEW v_buddy_matches AS
SELECT r.request_id, r.sender_id   AS user_id, r.receiver_id AS matched_user_id, r.updated_at AS matched_at
FROM   buddy_requests r
WHERE  r.status = 'accepted'
UNION ALL
SELECT r.request_id, r.receiver_id AS user_id, r.sender_id   AS matched_user_id, r.updated_at AS matched_at
FROM   buddy_requests r
WHERE  r.status = 'accepted';

CREATE OR REPLACE VIEW v_poll_results AS
SELECT
  o.poll_id,
  o.option_id,
  o.option_text,
  o.display_order,
  COUNT(v.vote_id) AS vote_count,
  ROUND(
    100 * COUNT(v.vote_id)::numeric /
    NULLIF((SELECT COUNT(*) FROM votes tv WHERE tv.poll_id = o.poll_id), 0),
    2
  ) AS vote_percentage
FROM poll_options o
LEFT JOIN votes v ON v.option_id = o.option_id
GROUP BY o.poll_id, o.option_id, o.option_text, o.display_order;

-- ------------------------------------------------------------
-- created_by must be an admin (competitions and polls)
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_assert_created_by_admin()
RETURNS TRIGGER AS $$
DECLARE
  v_role VARCHAR(16);
BEGIN
  -- On UPDATE, only re-check when created_by actually changed, so an
  -- ordinary edit does not fail because the original admin was demoted.
  IF TG_OP = 'UPDATE' AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by THEN
    RETURN NEW;
  END IF;

  IF NEW.created_by IS NOT NULL THEN
    SELECT role INTO v_role FROM users WHERE user_id = NEW.created_by;
    IF v_role IS NULL OR v_role <> 'admin' THEN
      RAISE EXCEPTION '%.created_by must reference a user with role = admin', TG_TABLE_NAME;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_competitions_admin_bi ON competitions;
CREATE TRIGGER trg_competitions_admin_bi
BEFORE INSERT ON competitions
FOR EACH ROW EXECUTE FUNCTION trg_assert_created_by_admin();

DROP TRIGGER IF EXISTS trg_competitions_admin_bu ON competitions;
CREATE TRIGGER trg_competitions_admin_bu
BEFORE UPDATE ON competitions
FOR EACH ROW EXECUTE FUNCTION trg_assert_created_by_admin();

DROP TRIGGER IF EXISTS trg_polls_admin_bi ON polls;
CREATE TRIGGER trg_polls_admin_bi
BEFORE INSERT ON polls
FOR EACH ROW EXECUTE FUNCTION trg_assert_created_by_admin();

DROP TRIGGER IF EXISTS trg_polls_admin_bu ON polls;
CREATE TRIGGER trg_polls_admin_bu
BEFORE UPDATE ON polls
FOR EACH ROW EXECUTE FUNCTION trg_assert_created_by_admin();

-- ------------------------------------------------------------
-- no voting on a closed or expired poll
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION trg_assert_poll_open()
RETURNS TRIGGER AS $$
DECLARE
  v_status  VARCHAR(16);
  v_ends_at TIMESTAMP;
BEGIN
  SELECT status, ends_at INTO v_status, v_ends_at FROM polls WHERE poll_id = NEW.poll_id;
  IF v_status IS DISTINCT FROM 'open'
     OR (v_ends_at IS NOT NULL AND v_ends_at <= CURRENT_TIMESTAMP) THEN
    RAISE EXCEPTION 'Cannot vote: this poll is closed';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_votes_poll_open_bi ON votes;
CREATE TRIGGER trg_votes_poll_open_bi
BEFORE INSERT ON votes
FOR EACH ROW EXECUTE FUNCTION trg_assert_poll_open();


-- ############################################################
-- # 009_relax_email_domain.sql
-- ############################################################

-- ============================================================
-- Migration 009 : allow any valid email domain
-- ------------------------------------------------------------
-- The product accepts @gmail.com, @yahoo.com, @outlook.com and any
-- other valid address. Registration was previously restricted to
-- Gmail in TWO places, both of which had to change together:
--     1. backend/validators/auth.validator.js  (GMAIL_REGEX -> EMAIL_REGEX)
--     2. this CHECK constraint on users.email
-- Removing only the validator would still fail at the database with
-- a check_violation (SQLSTATE 23514).
--
-- The address is still format-validated, and the service lowercases
-- it before insert, so the pattern is lowercase-only by design.
-- Existing Gmail addresses remain valid under the broader rule.
-- ============================================================

ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_email_gmail;

ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_email_format;
ALTER TABLE users ADD CONSTRAINT chk_users_email_format
  CHECK (email ~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$');
